/// # `GET /_matrix/client/r0/rooms/{roomId}/joined_members`
///
/// Lists all members of a room.
///
/// - The sender user must be in the room
/// - TODO: An appservice just needs a puppet joined
pub(crate) async fn joined_members_route(
	State(services): State<crate::State>,
	body: Ruma<joined_members::v3::Request>,
) -> Result<joined_members::v3::Response> {
	let is_joined = services
		.state_cache
		.is_joined(body.sender_user(), &body.room_id);

	let is_world_readable = services
		.state_accessor
		.room_state_get_content(&body.room_id, &StateEventType::RoomHistoryVisibility, "")
		.map_ok_or(false, |c: RoomHistoryVisibilityEventContent| {
			c.history_visibility == HistoryVisibility::WorldReadable
		});

	pin_mut!(is_joined, is_world_readable);
	if !is_joined.or(is_world_readable).await {
		return Err!(Request(Forbidden("You aren't a member of the room.")));
	}

	Ok(joined_members::v3::Response {
		joined: services
			.state_accessor
			.room_state_full(&body.room_id)
			.ready_filter_map(Result::ok)
			.ready_filter(|((ty, _), _)| *ty == StateEventType::RoomMember)
			.map(at!(1))
			.ready_filter_map(|pdu| {
				let content = pdu.get_content::<RoomMemberEventContent>().ok()?;

				let matches = content.membership == MembershipState::Join;

				matches.then(|| {
					let sender = pdu.sender().to_owned();
					let member = RoomMember {
						display_name: content.displayname,
						avatar_url: content.avatar_url,
					};

					(sender, member)
				})
			})
			.collect()
			.boxed()
			.await,
	})
}

pub(crate) async fn get_member_events_route(
	State(services): State<crate::State>,
	body: Ruma<get_member_events::v3::Request>,
) -> Result<get_member_events::v3::Response> {
	if !services
		.state_accessor
		.user_can_see_state_events(body.sender_user(), &body.room_id)
		.await
	{
		return Err!(Request(Forbidden(
			"You aren't a member of the room and weren't previously a member of the room."
		)));
	}

	let at: Option<PduCount> = body
		.at
		.as_deref()
		.map(str::parse)
		.transpose()
		.map_err(|_| err!(Request(InvalidParam("Invalid `at` token."))))?;

	let shortstatehash = match at {
		| None => services
			.state
			.get_room_shortstatehash(&body.room_id)
			.await
			.map_err(|e| err!(Database("Missing state for {:?}: {e:?}", body.room_id)))?,

		| Some(at) =>
			services
				.timeline
				.shortstatehash_after(&body.room_id, at)
				.await?,
	};

	let membership = body.membership.as_ref();
	let not_membership = body.not_membership.as_ref();
	let membership_filter = |content: &RoomMemberEventContent| {
		membership.is_none_or(is_equal_to!(&content.membership))
			&& not_membership.is_none_or(is_not_equal_to!(&content.membership))
	};

	Ok(get_member_events::v3::Response {
		chunk: services
			.state_accessor
			.state_full(shortstatehash)
			.ready_filter(|((ty, _), _)| *ty == StateEventType::RoomMember)
			.map(at!(1))
			.ready_filter(|pdu| {
				pdu.get_content::<RoomMemberEventContent>()
					.as_ref()
					.is_ok_and(membership_filter)
			})
			.map(Event::into_format)
			.collect()
			.boxed()
			.await,
	})
}

/// GET `/_matrix/client/v3/rooms/{roomId}/initialSync`
pub(crate) async fn room_initial_sync_route(
	State(services): State<crate::State>,
	body: Ruma<Request>,
) -> Result<Response> {
	let room_id = &body.room_id;
	let sender_user = body.sender_user();

	// `user_membership` uses `Ban` when a once-joined user's left row was forgotten.
	let cached_membership = services
		.state_cache
		.user_membership(sender_user, room_id)
		.await;

	matches!(cached_membership.as_ref(), Some(MembershipState::Ban))
		.is_false()
		.ok_or_else(|| err!(Request(Forbidden("No room preview available."))))?;

	services
		.state_accessor
		.user_can_see_state_events(sender_user, room_id)
		.await
		.ok_or_else(|| err!(Request(Forbidden("No room preview available."))))?;

	let current_shortstatehash = services
		.state
		.get_room_shortstatehash(room_id)
		.await?;

	let member = services
		.state_accessor
		.state_get(current_shortstatehash, &RoomMember, sender_user.as_str())
		.await
		.optional()?;

	let membership = member
		.as_ref()
		.map(Event::get_content)
		.transpose()?
		.map(|content: RoomMemberEventContent| content.membership);

	let next_batch = services.globals.current_count();
	let departure = membership
		.as_ref()
		.filter(|membership| matches!(membership, MembershipState::Leave | MembershipState::Ban))
		.zip(member.as_ref())
		.map(|(membership, pdu)| {
			departure_snapshot(
				&services,
				room_id,
				pdu,
				membership.to_owned(),
				current_shortstatehash,
			)
			.left_future()
		});

	let current_snapshot = ok((PduCount::Normal(next_batch), current_shortstatehash, membership));
	let (timeline_end, shortstatehash, membership) = departure
		.unwrap_or_else(|| current_snapshot.right_future())
		.await?;

	let visibility = services.directory.visibility(room_id).map(Ok);
	let limit = body.limit.unwrap_or(LIMIT_MAX).min(LIMIT_MAX);
	let state = services
		.state_accessor
		.state_full_pdus_strict(shortstatehash)
		.map_ok(Event::into_format)
		.try_collect::<Vec<_>>();

	let events = services
		.timeline
		.pdus_rev(Some(sender_user), room_id, Some(timeline_end.saturating_add(1)))
		.wide_and_then(|item| visibility_filter(&services, item, sender_user).map(Ok))
		.ready_try_filter_map(Ok)
		.try_take(limit)
		.try_collect()
		.map_ok(|mut vec: Vec<_>| {
			vec.reverse();
			vec
		});

	let account_data = services
		.account_data
		.changes_since_fallible(
			Some(room_id),
			sender_user,
			0,
			Some(timeline_end.into_normal().into_unsigned()),
		)
		.ready_try_filter_map(|e| Ok(extract_variant!(e, AnyRawAccountDataEvent::Room)))
		.try_collect::<Vec<_>>();

	let (visibility, state, events, account_data) = try_join4(visibility, state, events, account_data)
			.boxed() // erase the state stream's higher-ranked event lifetime
			.await?;

	Ok(Response {
		room_id: room_id.to_owned(),
		membership,
		visibility: visibility.into(),
		account_data: Some(account_data),
		state: state.into(),
		messages: PaginationChunk {
			start: events
				.first()
				.map(at!(0))
				.as_ref()
				.map(ToString::to_string),

			end: events
				.last()
				.map(at!(0))
				.as_ref()
				.map_or_else(|| timeline_end.to_string(), ToString::to_string),

			chunk: events
				.into_iter()
				.map(at!(1))
				.map(Event::into_format)
				.collect(),
		}
		.into(),
	})
}

